(189286, 11027, 2170, '<td valign="top">Lighting on the side of the face is too harsh -- washes out the hairline.  I like the wrinkles on his nose, though.</td>', 'Lighting on the side of the face is too harsh -- washes out the hairline.  I like the wrinkles on his nose, though.', '2003-01-13 17:22:51.000000', NULL, 1),
(189288, 10819, 2170, '<td valign="top">How dare you!  LOL.  This is really subtle, but very good.  We also misspell colour, theatre, and shoppe, and totally mispronouce aluminum.  Better watch it, or our trigger happy president will bomb you.</td>', 'How dare you!  LOL.  This is really subtle, but very good.  We also misspell colour, theatre, and shoppe, and totally mispronouce aluminum.  Better watch it, or our trigger happy president will bomb you.', '2003-01-13 17:25:18.000000', NULL, 1),
