(189313, 10813, 5009, '<td valign="top">For me the number one winner picture! Its cool!</td>', 'For me the number one winner picture! Its cool!', '2003-01-13 17:38:12.000000', NULL, 1),
(189411, 10734, 1829, '<td valign="top">This is something my kids would do to their barbies.  Anyhow, I love the lighting and the cloth in which you have set her on.  It gives a nice soft feeling.  Great soft shadow work here as well.  Certainly meets the challenge.  Great Job..GL</td>', 'This is something my kids would do to their barbies.  Anyhow, I love the lighting and the cloth in which you have set her on.  It gives a nice soft feeling.  Great soft shadow work here as well.  Certainly meets the challenge.  Great Job..GL', '2003-01-13 18:22:59.000000', NULL, 1),
(189415, 10896, 1829, '<td valign="top">You can see the expressive notion on that girls face, it is excellent.  The way he has his hand as if he is talking to her.  Excellent capture of a conversation.  I hope this photo does well.   GL</td>', 'You can see the expressive notion on that girls face, it is excellent.  The way he has his hand as if he is talking to her.  Excellent capture of a conversation.  I hope this photo does well.   GL', '2003-01-13 18:24:44.000000', NULL, 1),
(189416, 11003, 1829, '<td valign="top">Beautifully done.  I''m trying to guess who''s this one is from.  MMM let me think about it.</td>', 'Beautifully done.  I''m trying to guess who''s this one is from.  MMM let me think about it.', '2003-01-13 18:25:10.000000', NULL, 1),
(189465, 10813, 4388, '<td valign="top">not only clever but a very nice image..</td>', 'not only clever but a very nice image..', '2003-01-13 18:46:30.000000', NULL, 1),
(189466, 10721, 4388, '<td valign="top">my favorite.</td>', 'my favorite.', '2003-01-13 18:47:05.000000', NULL, 1),
(189468, 10889, 4388, '<td valign="top">sad but true, one of my favorites.</td>', 'sad but true, one of my favorites.', '2003-01-13 18:47:32.000000', NULL, 1),
(189474, 10952, 4388, '<td valign="top">what a pose!</td>', 'what a pose!', '2003-01-13 18:48:00.000000', NULL, 1),
(189475, 10949, 4388, '<td valign="top">love that smile!</td>', 'love that smile!', '2003-01-13 18:48:16.000000', NULL, 1),
(189570, 10974, 3080, '<td valign="top">LOL.  Couldn''t see the pencil coming out of the nose in the thumbnail.  Then when it popped up in the big version definately funny.  The shadow on the left side of the face (our right) is a bit too dark for me.  I think that a little lighting from that side would help us to see that the pencil was going into the ear.  The shadow kind of blocks that out a bit right now.  I like the angle and framong/cropping.  The border is nice, and the focus seems just fine to me.  Good luck in the challenge.</td>', 'LOL.  Couldn''t see the pencil coming out of the nose in the thumbnail.  Then when it popped up in the big version definately funny.  The shadow on the left side of the face (our right) is a bit too dark for me.  I think that a little lighting from that side would help us to see that the pencil was going into the ear.  The shadow kind of blocks that out a bit right now.  I like the angle and framong/cropping.  The border is nice, and the focus seems just fine to me.  Good luck in the challenge.', '2003-01-13 19:40:41.000000', NULL, 1),
(189598, 11021, 4494, '<td valign="top">LOL, not very high-tech is it. :)</td>', 'LOL, not very high-tech is it. :)', '2003-01-13 20:29:10.000000', NULL, 1),
(189600, 10886, 4494, '<td valign="top">HAAAHAHAHAHAAA!!!!  So funny!</td>', 'HAAAHAHAHAHAAA!!!!  So funny!', '2003-01-13 20:29:52.000000', NULL, 1),
(189605, 11045, 4494, '<td valign="top">Hehehee, looks like a real fortune.  I like the ones that say "You Love Chinese Food".  :)</td>', 'Hehehee, looks like a real fortune.  I like the ones that say "You Love Chinese Food".  :)', '2003-01-13 20:31:22.000000', NULL, 1),
(189609, 11003, 4494, '<td valign="top">Umm Umm.</td>', 'Umm Umm.', '2003-01-13 20:33:23.000000', NULL, 1),
(189614, 10986, 4494, '<td valign="top">LOL dead baby jokes!!!  Geez what''s this world coming to. :)  What''s red and green and goes 90 miles an hour?  .....A frog in a blender. Nuk nuk nuk.</td>', 'LOL dead baby jokes!!!  Geez what''s this world coming to. :)  What''s red and green and goes 90 miles an hour?  .....A frog in a blender. Nuk nuk nuk.', '2003-01-13 20:35:25.000000', NULL, 1),
(189624, 10819, 4494, '<td valign="top">LOL you spelled "spelt" wrong. :)   And I''ve always thought it was Brits who spell those words wrong:  Recognise, colour...  Well look...  in that book of yours they even spelled (not spelt) "Americanize" incorrectly!! :D  <br/></td>', 'LOL you spelled "spelt" wrong. :)   And I''ve always thought it was Brits who spell those words wrong:  Recognise, colour...  Well look...  in that book of yours they even spelled (not spelt) "Americanize" incorrectly!! :D  ', '2003-01-13 20:41:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(189628, 10766, 4494, '<td valign="top">hahahaaa.  Looks like a rooster.</td>', 'hahahaaa.  Looks like a rooster.', '2003-01-13 20:42:46.000000', NULL, 1),
(189633, 11013, 4494, '<td valign="top">LMAO!</td>', 'LMAO!', '2003-01-13 20:43:27.000000', NULL, 1),
(189638, 11029, 4494, '<td valign="top">Hehe, based off of that great "Dog Eat Frog" picture a while back right?</td>', 'Hehe, based off of that great "Dog Eat Frog" picture a while back right?', '2003-01-13 20:45:22.000000', NULL, 1),
(189641, 10889, 4494, '<td valign="top">Oh man that''s funny.  You should have saved this one for the "Road Signs" challenge this week.  Although it''s not really a "road" sign but...</td>', 'Oh man that''s funny.  You should have saved this one for the "Road Signs" challenge this week.  Although it''s not really a "road" sign but...', '2003-01-13 20:47:10.000000', NULL, 1),
(189646, 10954, 4494, '<td valign="top">Hahaha, that''s pretty good.</td>', 'Hahaha, that''s pretty good.', '2003-01-13 20:49:30.000000', NULL, 1),
(189659, 11009, 3080, '<td valign="top">At first I didn''t think this was that funny, but when I looked at it further, it made me laugh.  Silly looking guys.  I like the background as well, and the angle and framing/cropping is good.  I like the lighting a lot.  Really adds to the drama of these guys.  Great shot and good luck in the challenge.</td>', 'At first I didn''t think this was that funny, but when I looked at it further, it made me laugh.  Silly looking guys.  I like the background as well, and the angle and framing/cropping is good.  I like the lighting a lot.  Really adds to the drama of these guys.  Great shot and good luck in the challenge.', '2003-01-13 20:55:38.000000', NULL, 1),
(189733, 10767, 5212, '<td valign="top">Love the cropping and this done in b/w.  It meets the challenge well.  It almost looks like the kitty is smoking a cigarrette.</td>', 'Love the cropping and this done in b/w.  It meets the challenge well.  It almost looks like the kitty is smoking a cigarrette.', '2003-01-13 21:55:12.000000', NULL, 1),
(189741, 10738, 5212, '<td valign="top">Very well meets the challenge.  Good capture of the subjects.  The green behind the guys is a little bit distracting to me, although I''m assuming it''s their tails?</td>', 'Very well meets the challenge.  Good capture of the subjects.  The green behind the guys is a little bit distracting to me, although I''m assuming it''s their tails?', '2003-01-13 22:00:18.000000', NULL, 1),
(189743, 10826, 5212, '<td valign="top">Would like to have seen this lightened up with increased contrast to bring out a bit of detail.  Good composition and subject meets the challenge.</td>', 'Would like to have seen this lightened up with increased contrast to bring out a bit of detail.  Good composition and subject meets the challenge.', '2003-01-13 22:01:05.000000', NULL, 1),
(189751, 10889, 2, '<td valign="top">hehhehehe... very nice :)  What made you decide to show the tree and just the gun store, though?</td>', 'hehhehehe... very nice :)  What made you decide to show the tree and just the gun store, though?', '2003-01-13 22:04:31.000000', NULL, 1),
(189754, 10960, 2, '<td valign="top">Took me a minute.  hehehehe.. buried cable.  funny :)  I like the shot, but I really don''t like the border... seems unnecessarily distracting.</td>', 'Took me a minute.  hehehehe.. buried cable.  funny :)  I like the shot, but I really don''t like the border... seems unnecessarily distracting.', '2003-01-13 22:05:34.000000', NULL, 1),
(189757, 10727, 5212, '<td valign="top">Great shot of the owl, must have taken some work to catch this pose. Wish the lighting had not been so harsh, or his right side could have been brightened more, although the flip side of that is the lighting on his front side draws your eye to his face.</td>', 'Great shot of the owl, must have taken some work to catch this pose. Wish the lighting had not been so harsh, or his right side could have been brightened more, although the flip side of that is the lighting on his front side draws your eye to his face.', '2003-01-13 22:06:48.000000', NULL, 1),
(189758, 10738, 2, '<td valign="top">Great caption for a good picture.  The overexposure seems unnecessary to me, though.</td>', 'Great caption for a good picture.  The overexposure seems unnecessary to me, though.', '2003-01-13 22:06:54.000000', NULL, 1),
(189760, 10828, 5212, '<td valign="top">This dog looks striped, and that to me is as much the humorous part of the photo as his expression.  This might have been even funnier without the lighting effects to me.</td>', 'This dog looks striped, and that to me is as much the humorous part of the photo as his expression.  This might have been even funnier without the lighting effects to me.', '2003-01-13 22:08:02.000000', NULL, 1),
(189762, 10829, 2, '<td valign="top">Is this title an allusion?  It seems very familiar.  Either way, it''s very funny for the picture.  The composition of the shot itself is a bit mundane.  I think you should have gotten closer up filled the frame some more.  The shot is 60% trees, and that doesn''t help the photograph.</td>', 'Is this title an allusion?  It seems very familiar.  Either way, it''s very funny for the picture.  The composition of the shot itself is a bit mundane.  I think you should have gotten closer up filled the frame some more.  The shot is 60% trees, and that doesn''t help the photograph.', '2003-01-13 22:09:10.000000', NULL, 1),
(189763, 10766, 2, '<td valign="top">The lack of a sharp focus is pretty distracting, and so is the border</td>', 'The lack of a sharp focus is pretty distracting, and so is the border', '2003-01-13 22:10:26.000000', NULL, 1),
(189765, 11021, 5212, '<td valign="top">Cute idea.. I like the way the lighting helps draw the eye to the subject in this picture and their is good contrast, use of color and clarity in the shot.</td>', 'Cute idea.. I like the way the lighting helps draw the eye to the subject in this picture and their is good contrast, use of color and clarity in the shot.', '2003-01-13 22:11:45.000000', NULL, 1),
(189767, 11013, 5212, '<td valign="top">Very, very funny.  I would say I have been there and done that if my name wasn''t attached to my comments.  Interesting angle of camera, use of thirds and clarity of image.</td>', 'Very, very funny.  I would say I have been there and done that if my name wasn''t attached to my comments.  Interesting angle of camera, use of thirds and clarity of image.', '2003-01-13 22:12:48.000000', NULL, 1),
(189768, 10848, 5212, '<td valign="top">The title helps add humor to the image, but don''t know if I would look at this shot and immediately think humor.  This was a tough challenge.  I do like the composition, colors and depth in this photo, however.</td>', 'The title helps add humor to the image, but don''t know if I would look at this shot and immediately think humor.  This was a tough challenge.  I do like the composition, colors and depth in this photo, however.', '2003-01-13 22:13:49.000000', NULL, 1),
(189769, 10989, 2, '<td valign="top">Without looking at the title, I thought this shot was technically well-done, but another shot of something mildly humorous without really making me laugh.  Then I saw the title, and it all came together =D  My one suggestion would be to try some different flashes, as the top gets darker and loses my attention.</td>', 'Without looking at the title, I thought this shot was technically well-done, but another shot of something mildly humorous without really making me laugh.  Then I saw the title, and it all came together =D  My one suggestion would be to try some different flashes, as the top gets darker and loses my attention.', '2003-01-13 22:13:52.000000', NULL, 1),
(189771, 10721, 2, '<td valign="top">hehehe.  Neat picture.  Nice, sharp focus.</td>', 'hehehe.  Neat picture.  Nice, sharp focus.', '2003-01-13 22:14:16.000000', NULL, 1),
(189773, 10734, 2, '<td valign="top">Great shot.  I love the overblown whites and even the slight grain on the shot... it really fits the almost serial-killer feeling I get from the shot.  8.</td>', 'Great shot.  I love the overblown whites and even the slight grain on the shot... it really fits the almost serial-killer feeling I get from the shot.  8.', '2003-01-13 22:15:01.000000', NULL, 1),
(189784, 11021, 5705, '<td valign="top">This joke has been on the web for years--<br/>Need more original content.. :(</td>', 'This joke has been on the web for years--Need more original content.. :(', '2003-01-13 22:28:27.000000', NULL, 1),
(189801, 10819, 2, '<td valign="top">How do you like this joke?  ONE!  (ok ok just kidding... this is actually quite funny.  Where on earth did you find it?)</td>', 'How do you like this joke?  ONE!  (ok ok just kidding... this is actually quite funny.  Where on earth did you find it?)', '2003-01-13 22:34:46.000000', NULL, 1),
(189802, 11015, 2, '<td valign="top">Really funny photo.  Great choice of angle.  Less than great choice of border :)</td>', 'Really funny photo.  Great choice of angle.  Less than great choice of border :)', '2003-01-13 22:35:28.000000', NULL, 1),
(189804, 10961, 2, '<td valign="top">I love that this is impromptu humor.  Of course, the slight misfocus comes with the territory.  Good effort overall.</td>', 'I love that this is impromptu humor.  Of course, the slight misfocus comes with the territory.  Good effort overall.', '2003-01-13 22:36:05.000000', NULL, 1),
(189808, 10927, 2, '<td valign="top">Your model''s pose is classic... make sure you tell him he did a great job.  Funny, funny picture :)</td>', 'Your model''s pose is classic... make sure you tell him he did a great job.  Funny, funny picture :)', '2003-01-13 22:37:27.000000', NULL, 1),
(189810, 11027, 2, '<td valign="top">heheheheh.  Great shot... love the angle!  Great lighting, too.</td>', 'heheheheh.  Great shot... love the angle!  Great lighting, too.', '2003-01-13 22:37:53.000000', NULL, 1),
(189818, 11030, 2, '<td valign="top">Classic :)  My mom would really appreciate this one.</td>', 'Classic :)  My mom would really appreciate this one.', '2003-01-13 22:40:01.000000', NULL, 1),
(189830, 10986, 2, '<td valign="top">I saw a page full of these on the internet, and having the sick sense of humor I do, I was quick to send it to Langdon.  The jokes are funny... taking a picture of jokes isn''t.</td>', 'I saw a page full of these on the internet, and having the sick sense of humor I do, I was quick to send it to Langdon.  The jokes are funny... taking a picture of jokes isn''t.', '2003-01-13 22:42:14.000000', NULL, 1),
(189836, 10836, 3320, '<td valign="top">voting on the \\\''smile/laugh factor\\\'' this week , less on the quality.<br/>5. Lionel<br/>I do not get it .. what the tube the bird is on ? please pm me. Lionelm<br/></td>', 'voting on the \\\''smile/laugh factor\\\'' this week , less on the quality.5. LionelI do not get it .. what the tube the bird is on ? please pm me. Lionelm', '2003-01-13 22:43:39.000000', NULL, 1),
(189837, 10974, 2, '<td valign="top">Great shot.  I love the greenish tone on the whole image.  If I didn''t already know who this was taken by, I''d assume the photographer has done portraits before.</td>', 'Great shot.  I love the greenish tone on the whole image.  If I didn''t already know who this was taken by, I''d assume the photographer has done portraits before.', '2003-01-13 22:43:46.000000', NULL, 1),
(189849, 10954, 4615, '<td valign="top">great expression.  Maybe you could get a little closer so we could see more of it.</td>', 'great expression.  Maybe you could get a little closer so we could see more of it.', '2003-01-13 22:47:31.000000', NULL, 1),
(189851, 11014, 5212, '<td valign="top">I''m not sure that this photo makes me laugh, although the title  helps a bit.  Great macro shot, though and very appropriate for b/w.</td>', 'I''m not sure that this photo makes me laugh, although the title  helps a bit.  Great macro shot, though and very appropriate for b/w.', '2003-01-13 22:48:10.000000', NULL, 1),
(189854, 10878, 5212, '<td valign="top">Wish there wasn''t so much dark in this photo.  Black animals are so hard to catch on film.  The puppy in front looks clear.  Maybe a lighter background might have helped and some level or brightness adjustment to bring out more detail.</td>', 'Wish there wasn''t so much dark in this photo.  Black animals are so hard to catch on film.  The puppy in front looks clear.  Maybe a lighter background might have helped and some level or brightness adjustment to bring out more detail.', '2003-01-13 22:49:24.000000', NULL, 1),
(189857, 10920, 5212, '<td valign="top">This one makes me laugh!  The shades add to the shot.  Good luck.</td>', 'This one makes me laugh!  The shades add to the shot.  Good luck.', '2003-01-13 22:50:05.000000', NULL, 1),
(189859, 10886, 5212, '<td valign="top">Very , very funny.  Good cropping, lighting and composition.</td>', 'Very , very funny.  Good cropping, lighting and composition.', '2003-01-13 22:50:55.000000', NULL, 1),
(189860, 10991, 5212, '<td valign="top">Good way to meet the challenge.  Like how the hand comes out from nowhere and the pen looks like it''s floating.</td>', 'Good way to meet the challenge.  Like how the hand comes out from nowhere and the pen looks like it''s floating.', '2003-01-13 22:52:02.000000', NULL, 1),
(189862, 10766, 5212, '<td valign="top">Funny with the title.  I am really looking for photos that say humor without words for my highest ratings in the challenge, though.  Also the face looks a bit unfocused and the lighting might be a tad better.  Good luck anyway!</td>', 'Funny with the title.  I am really looking for photos that say humor without words for my highest ratings in the challenge, though.  Also the face looks a bit unfocused and the lighting might be a tad better.  Good luck anyway!', '2003-01-13 22:53:28.000000', NULL, 1),
(189867, 10738, 5753, '<td valign="top">Cracked me up!  I can''t vote on this, but a chuckle from me is a least worth a 8.</td>', 'Cracked me up!  I can''t vote on this, but a chuckle from me is a least worth a 8.', '2003-01-13 22:56:56.000000', NULL, 1),
(189869, 10766, 3280, '<td valign="top">Good shot, but I really wish we had a bit more focus.  It appears that you took it from far off and cropped it in.  I love the title.</td>', 'Good shot, but I really wish we had a bit more focus.  It appears that you took it from far off and cropped it in.  I love the title.', '2003-01-13 23:04:22.000000', NULL, 1),
(189871, 10952, 3280, '<td valign="top">I love the slippers.  Can she play How Much is That Doggie in the Window?  Good job, I like the sepia for this shot. A little too much light in the back of the shot burning out the keys.</td>', 'I love the slippers.  Can she play How Much is That Doggie in the Window?  Good job, I like the sepia for this shot. A little too much light in the back of the shot burning out the keys.', '2003-01-13 23:05:54.000000', NULL, 1),
(189872, 10954, 3280, '<td valign="top">Pretty realistic looking.  Perhaps could have used a little more saturation.</td>', 'Pretty realistic looking.  Perhaps could have used a little more saturation.', '2003-01-13 23:06:35.000000', NULL, 1),
(189873, 10721, 3280, '<td valign="top">This is a great shot, one of my faves this week.  I really smiled back at him!!  My only nit is that it seems to be leaning just a bit to the left. Super job!</td>', 'This is a great shot, one of my faves this week.  I really smiled back at him!!  My only nit is that it seems to be leaning just a bit to the left. Super job!', '2003-01-13 23:08:05.000000', NULL, 1),
(189874, 10920, 3280, '<td valign="top">Cute, good focus for what appears to be a moving target. A little too close to the curtain with the shadows though.</td>', 'Cute, good focus for what appears to be a moving target. A little too close to the curtain with the shadows though.', '2003-01-13 23:09:10.000000', NULL, 1),
(189875, 10886, 2204, '<td valign="top">A great pun on some past submissions and incredibly funny!!!</td>', 'A great pun on some past submissions and incredibly funny!!!', '2003-01-13 23:09:50.000000', NULL, 1),
(189876, 11029, 3280, '<td valign="top">Cute idea!  Who likes those ole frogs anyway.  Your background seems just a bit grainey.</td>', 'Cute idea!  Who likes those ole frogs anyway.  Your background seems just a bit grainey.', '2003-01-13 23:10:31.000000', NULL, 1),
